            else
            {
                config_parse(data);
                ++currentNotecardLine;
                notecardQueryId = llGetNotecardLine(notecardName, currentNotecardLine);
            }
        }
    }

    timer()
    {
        llSetTimerEvent((float)FALSE);

        if (dialogHandle)
