    {
        integer i = 0;
        for (;i<n;++i)
        {
            if (llOverMyLand(llDetectedKey(i)))
            {
                if (~llSubStringIndex(llToLower(llDetectedName(i)), name))
                {
                    llOwnerSay("ejecting " + llDetectedName(i));
                    llEjectFromLand(llDetectedKey(i));
                }
            }
        }
    }
    no_sensor()
    {
        llOwnerSay("Avatar not found.");
    }
